sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =========================================
       DEFAULT FILTERS
       ========================================= */

    c.searchText = "";

    c.statusFilter = "all";

    c.priorityFilter = "all";

    c.processing = null;


    /* =========================================
       FILTER TICKETS
       ========================================= */

    c.filteredTickets = function() {

        var result = [];

        var tickets =
            c.data.tickets || [];


        for (var i = 0; i < tickets.length; i++) {

            var ticket = tickets[i];


            /* Search */

            var search =
                (c.searchText || "")
                .toLowerCase();


            var number =
                (ticket.number || "")
                .toLowerCase();


            var description =
                (ticket.short_description || "")
                .toLowerCase();


            if (
                search &&
                number.indexOf(search) === -1 &&
                description.indexOf(search) === -1
            ) {

                continue;

            }


            /* Status filter */

            if (
                c.statusFilter === "open" &&
                ticket.stateValue != "1"
            ) {

                continue;

            }


            if (
                c.statusFilter === "progress" &&
                ticket.stateValue != "2"
            ) {

                continue;

            }


            if (
                c.statusFilter === "resolved" &&
                ticket.stateValue != "6" &&
                ticket.stateValue != "7"
            ) {

                continue;

            }


            /* Priority filter */

            if (
                c.priorityFilter !== "all" &&
                ticket.priorityValue !=
                c.priorityFilter
            ) {

                continue;

            }


            result.push(ticket);

        }


        return result;

    };


    /* =========================================
       START TICKET
       ========================================= */

    c.startTicket = function(ticket) {

        if (!ticket) {
            return;
        }


        c.processing =
            ticket.sys_id;


        c.server.get({

            action: "start",

            sys_id:
                ticket.sys_id

        }).then(function(response) {

            c.processing = null;

            c.data.success =
                response.data.success;

            c.data.error =
                response.data.error;

            if (!response.data.error) {

                c.reload();

            }

        });

    };


    /* =========================================
       RESOLVE TICKET
       ========================================= */

    c.resolveTicket = function(ticket) {

        if (!ticket) {
            return;
        }


        var confirmed =
            window.confirm(
                "Are you sure you want to resolve " +
                ticket.number +
                "?"
            );


        if (!confirmed) {
            return;
        }


        c.processing =
            ticket.sys_id;


        c.server.get({

            action: "resolve",

            sys_id:
                ticket.sys_id

        }).then(function(response) {

            c.processing = null;

            c.data.success =
                response.data.success;

            c.data.error =
                response.data.error;

            if (!response.data.error) {

                c.reload();

            }

        });

    };


    /* =========================================
       ESCALATE TICKET
       ========================================= */

    c.escalateTicket = function(ticket) {

        if (!ticket) {
            return;
        }


        var confirmed =
            window.confirm(
                "Are you sure you want to escalate " +
                ticket.number +
                "?"
            );


        if (!confirmed) {
            return;
        }


        c.processing =
            ticket.sys_id;


        c.server.get({

            action: "escalate",

            sys_id:
                ticket.sys_id

        }).then(function(response) {

            c.processing = null;

            c.data.success =
                response.data.success;

            c.data.error =
                response.data.error;

            if (!response.data.error) {

                c.reload();

            }

        });

    };


    /* =========================================
       RELOAD
       ========================================= */

    c.reload = function() {

        c.server.get({}).then(function(response) {

            c.data =
                response.data;

        });

    };


    /* =========================================
       DASHBOARD
       ========================================= */

    c.goDashboard = function() {

        window.location.href =
            "?id=cfms_staff";

    };

};

sp_widget.css:
/* =========================================
   CFMS ASSIGNED TICKETS
   ========================================= */

.cfms-page {
  min-height: 100vh;
  background: #f0fbfc;
  padding: 30px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  color: #263238;
}


/* =========================================
   PAGE HEADER
   ========================================= */

.page-header {
  background: linear-gradient(
    135deg,
    #00acc1,
    #4dd0e1
  );

  color: white;
  border-radius: 18px;

  padding: 28px 32px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 25px;

  box-shadow: 0 8px 25px rgba(0, 172, 193, 0.18);
}

.page-header h1 {
  margin: 0 0 7px;
  font-size: 30px;
  font-weight: 700;
}

.page-header p {
  margin: 0;
  opacity: 0.95;
  font-size: 15px;
}


/* Dashboard button */

.back-btn {
  border: none;
  background: white;
  color: #008c9e;

  padding: 11px 18px;

  border-radius: 10px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;
}

.back-btn:hover {
  transform: translateY(-2px);
}


/* =========================================
   ALERTS
   ========================================= */

.alert {
  padding: 14px 18px;
  border-radius: 10px;
  margin-bottom: 20px;
  font-weight: 600;
}

.error-alert {
  background: #ffebee;
  color: #c62828;
  border: 1px solid #ef9a9a;
}

.success-alert {
  background: #e8f5e9;
  color: #2e7d32;
  border: 1px solid #a5d6a7;
}


/* =========================================
   STATISTICS
   ========================================= */

.stats-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 18px;

  margin-bottom: 25px;
}

.stat-card {
  background: white;

  border-radius: 15px;

  padding: 22px;

  display: flex;
  align-items: center;

  gap: 15px;

  box-shadow:
    0 4px 15px rgba(38, 50, 56, 0.07);

  border: 1px solid #e0f2f3;
}

.stat-icon {
  width: 50px;
  height: 50px;

  border-radius: 12px;

  background: #e0f7fa;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 23px;
}

.stat-card span {
  display: block;

  font-size: 13px;

  color: #78909c;

  margin-bottom: 5px;
}

.stat-card strong {
  display: block;

  font-size: 27px;

  color: #263238;
}


/* =========================================
   FILTER
   ========================================= */

.filter-card {
  background: white;

  padding: 18px;

  border-radius: 15px;

  display: flex;

  gap: 15px;

  margin-bottom: 20px;

  box-shadow:
    0 4px 15px rgba(38, 50, 56, 0.06);
}

.search-box {
  flex: 1;

  display: flex;

  align-items: center;

  gap: 10px;

  background: #f7fcfd;

  border: 1px solid #dceff1;

  border-radius: 10px;

  padding: 0 14px;
}

.search-box input {
  border: none;

  outline: none;

  background: transparent;

  width: 100%;

  padding: 12px 0;

  font-size: 14px;
}

.filter-card select {
  min-width: 160px;

  border: 1px solid #dceff1;

  background: #f7fcfd;

  border-radius: 10px;

  padding: 11px 14px;

  color: #37474f;

  outline: none;
}


/* =========================================
   TICKETS CARD
   ========================================= */

.tickets-card {
  background: white;

  border-radius: 17px;

  padding: 25px;

  box-shadow:
    0 5px 20px rgba(38, 50, 56, 0.07);
}

.section-title {
  display: flex;

  justify-content: space-between;

  align-items: center;

  padding-bottom: 20px;

  border-bottom: 1px solid #edf5f6;
}

.section-title h2 {
  margin: 0 0 5px;

  font-size: 21px;
}

.section-title p {
  margin: 0;

  color: #78909c;

  font-size: 13px;
}

.ticket-count {
  background: #e0f7fa;

  color: #008c9e;

  padding: 7px 13px;

  border-radius: 20px;

  font-size: 13px;

  font-weight: 600;
}


/* =========================================
   TICKET ROW
   ========================================= */

.ticket-row {
  display: grid;

  grid-template-columns:
    1fr auto auto;

  align-items: center;

  gap: 25px;

  padding: 22px 5px;

  border-bottom: 1px solid #edf5f6;
}

.ticket-row:last-child {
  border-bottom: none;
}

.ticket-number {
  color: #0097a7;

  font-size: 13px;

  font-weight: 700;

  margin-bottom: 5px;
}

.ticket-main h3 {
  margin: 0 0 10px;

  font-size: 16px;

  font-weight: 600;

  color: #263238;
}

.ticket-meta {
  display: flex;

  gap: 18px;

  flex-wrap: wrap;

  color: #78909c;

  font-size: 12px;
}


/* =========================================
   BADGES
   ========================================= */

.ticket-status {
  display: flex;

  flex-direction: column;

  gap: 7px;

  align-items: center;
}

.status-badge,
.priority-badge {
  min-width: 90px;

  text-align: center;

  padding: 6px 10px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;
}


/* Status */

.status-open {
  background: #fff3e0;
  color: #ef6c00;
}

.status-progress {
  background: #e3f2fd;
  color: #1565c0;
}

.status-resolved {
  background: #e8f5e9;
  color: #2e7d32;
}


/* Priority */

.priority-critical {
  background: #ffebee;
  color: #c62828;
}

.priority-high {
  background: #fff3e0;
  color: #ef6c00;
}

.priority-medium {
  background: #fffde7;
  color: #827717;
}

.priority-low {
  background: #e8f5e9;
  color: #2e7d32;
}


/* =========================================
   ACTION BUTTONS
   ========================================= */

.ticket-actions {
  display: flex;

  gap: 7px;

  flex-wrap: wrap;

  justify-content: flex-end;
}

.action-btn {
  border: none;

  border-radius: 8px;

  padding: 8px 12px;

  font-size: 12px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;
}

.action-btn:hover {
  transform: translateY(-1px);
}

.action-btn:disabled {
  opacity: 0.5;

  cursor: not-allowed;
}

.start-btn {
  background: #e0f7fa;
  color: #008c9e;
}

.resolve-btn {
  background: #e8f5e9;
  color: #2e7d32;
}

.escalate-btn {
  background: #fff3e0;
  color: #ef6c00;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-state {
  text-align: center;

  padding: 70px 20px;
}

.empty-icon {
  font-size: 50px;

  margin-bottom: 15px;
}

.empty-state h3 {
  margin: 0 0 8px;

  font-size: 20px;
}

.empty-state p {
  color: #78909c;

  margin: 0;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1000px) {

  .stats-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .ticket-row {
    grid-template-columns: 1fr;
    gap: 15px;
  }

  .ticket-status {
    flex-direction: row;
    justify-content: flex-start;
  }

  .ticket-actions {
    justify-content: flex-start;
  }
}


@media (max-width: 700px) {

  .cfms-page {
    padding: 15px;
  }

  .page-header {
    padding: 22px;

    flex-direction: column;

    align-items: flex-start;

    gap: 15px;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .filter-card {
    flex-direction: column;
  }

  .filter-card select {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName();

    data.total = 0;
    data.open = 0;
    data.inProgress = 0;
    data.resolved = 0;

    data.tickets = [];

    data.error = "";
    data.success = "";


    /* =========================================
       SECURITY
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;
    }


    if (!gs.hasRole("cfms_staff") && !gs.hasRole("admin")) {

        data.error = "You are not authorized to access Assigned Tickets.";

        data.redirect = "cfms_home";

        return;
    }


    /* =========================================
       ACTIONS
       ========================================= */

    if (input && input.action) {

        var action = input.action;

        var ticketID = input.sys_id;


        if (!ticketID) {

            data.error = "Ticket ID is missing.";

            return;
        }


        var ticket = new GlideRecord("incident");


        if (!ticket.get(ticketID)) {

            data.error = "Ticket not found.";

            return;
        }


        /* -----------------------------------------
           START TICKET
           ----------------------------------------- */

        if (action == "start") {

            ticket.state = 2;

            /*
             * If ticket is not assigned to anyone,
             * assign it to current staff member.
             */

            if (!ticket.assigned_to) {

                ticket.assigned_to = gs.getUserID();

            }

            ticket.work_notes =
                "CFMS staff started working on this ticket.";

            ticket.update();

            data.success =
                ticket.getValue("number") +
                " has been moved to In Progress.";

        }


        /* -----------------------------------------
           RESOLVE TICKET
           ----------------------------------------- */

        else if (action == "resolve") {

            ticket.state = 6;

            ticket.resolved_by = gs.getUserID();

            ticket.work_notes =
                "CFMS staff resolved this ticket.";

            ticket.update();

            data.success =
                ticket.getValue("number") +
                " has been resolved.";

        }


        /* -----------------------------------------
           ESCALATE TICKET
           ----------------------------------------- */

        else if (action == "escalate") {

            /*
             * Escalation follows the CFMS priority
             * routing logic.
             */

            var priority = ticket.getValue("priority");

            var groupName = "";

            if (priority == "1") {

                groupName = "Hostel Management Group";

            } else if (priority == "2") {

                groupName = "Hostel Admin Group";

            } else {

                groupName = "Hostel Management Group";

            }


            var group = new GlideRecord("sys_user_group");

            group.addQuery("name", groupName);

            group.setLimit(1);

            group.query();


            if (group.next()) {

                ticket.assignment_group =
                    group.getUniqueValue();

                ticket.work_notes =
                    "Ticket escalated by CFMS staff to " +
                    groupName + ".";

                ticket.update();

                data.success =
                    ticket.getValue("number") +
                    " has been escalated to " +
                    groupName + ".";

            } else {

                data.error =
                    "Escalation group '" +
                    groupName +
                    "' was not found.";

            }

        }


        return;
    }


    /* =========================================
       LOAD TICKETS
       ========================================= */

    var gr = new GlideRecord("incident");


    /*
     * Current model:
     *
     * 1. Tickets individually assigned to staff
     * OR
     * 2. Tickets assigned to a staff group
     *
     */

    var userID = gs.getUserID();


    /*
     * Get groups where current user is a member.
     */

    var groups = [];

    var membership = new GlideRecord("sys_user_grmember");

    membership.addQuery("user", userID);

    membership.query();


    while (membership.next()) {

        groups.push(
            membership.getValue("group")
        );

    }


    /*
     * Build ticket query.
     */

    var qc = gr.addQuery(
        "assigned_to",
        userID
    );


    if (groups.length > 0) {

        qc.addOrCondition(
            "assignment_group",
            "IN",
            groups.join(",")
        );

    }


    gr.orderByDesc("sys_updated_on");

    gr.query();


    /* =========================================
       BUILD RESPONSE
       ========================================= */

    while (gr.next()) {

        data.total++;


        var state =
            gr.getValue("state");

        var stateText =
            gr.getDisplayValue("state");


        /* -----------------------------------------
           STATUS COUNT
           ----------------------------------------- */

        if (state == "1") {

            data.open++;

        } else if (state == "2") {

            data.inProgress++;

        } else if (
            state == "6" ||
            state == "7"
        ) {

            data.resolved++;

        }


        /* -----------------------------------------
           STATUS CLASS
           ----------------------------------------- */

        var statusClass =
            "status-open";


        if (state == "2") {

            statusClass =
                "status-progress";

        } else if (
            state == "6" ||
            state == "7"
        ) {

            statusClass =
                "status-resolved";

        }


        /* -----------------------------------------
           PRIORITY
           ----------------------------------------- */

        var priority =
            gr.getValue("priority");

        var priorityText =
            gr.getDisplayValue("priority");

        var priorityClass =
            "priority-medium";


        if (priority == "1") {

            priorityText = "Critical";

            priorityClass =
                "priority-critical";

        } else if (priority == "2") {

            priorityText = "High";

            priorityClass =
                "priority-high";

        } else if (priority == "3") {

            priorityText = "Medium";

            priorityClass =
                "priority-medium";

        } else if (priority == "4") {

            priorityText = "Low";

            priorityClass =
                "priority-low";

        }


        /* -----------------------------------------
           TICKET DATA
           ----------------------------------------- */

        data.tickets.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getValue("number"),

            short_description:
                gr.getValue("short_description"),

            caller:
                gr.getDisplayValue("caller_id"),

            assignment_group:
                gr.getDisplayValue(
                    "assignment_group"
                ),

            assigned_to:
                gr.getDisplayValue(
                    "assigned_to"
                ),

            state:
                stateText,

            stateValue:
                state,

            statusClass:
                statusClass,

            priority:
                priorityText,

            priorityValue:
                priority,

            priorityClass:
                priorityClass,

            created:
                gr.getDisplayValue(
                    "sys_created_on"
                )

        });

    }

})();
